*{box-sizing:border-box} :root{--ink:#f7f0dc;--muted:#c9c7ae;--gold:#e7c879;--deep:#182820;--glass:rgba(25,39,31,.84);--line:rgba(240,225,183,.2)} html,body,#game{width:100%;height:100%;margin:0;overflow:hidden} body{background:#a7bc8a;color:var(--ink);font-family:'DM Sans',sans-serif;user-select:none;-webkit-user-select:none;touch-action:none} #game{position:relative;isolation:isolate} #world{display:block;width:100%;height:100%;outline:0}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(13,31,22,.55),transparent 25%,transparent 68%,rgba(16,30,22,.28)),radial-gradient(ellipse at center,transparent 55%,rgba(18,31,22,.22));z-index:1}.topbar{position:absolute;z-index:3;top:max(18px,env(safe-area-inset-top));left:28px;right:28px;display:flex;align-items:center;justify-content:space-between;pointer-events:none}.brand,.day-pill,.icon-btn{pointer-events:auto}.brand{display:flex;align-items:center;gap:11px;text-shadow:0 2px 9px #1b2e22}.brand-mark{width:40px;height:40px;border:1px solid rgba(238,215,154,.75);border-radius:50%;display:grid;place-items:center;color:#efd587;font-size:23px;background:rgba(30,48,37,.45)}.brand-name{font-family:Fraunces,serif;font-size:17px;letter-spacing:2px;line-height:1.1}.brand-sub{font-size:9px;letter-spacing:2.7px;color:#e4d7b4;margin-top:3px}.day-pill{position:absolute;left:50%;transform:translateX(-50%);border:1px solid rgba(249,231,184,.24);border-radius:30px;background:rgba(29,46,35,.53);backdrop-filter:blur(10px);padding:9px 16px;font-size:10px;font-weight:700;letter-spacing:1.3px}.sun-icon{color:#f3d982;margin-right:8px;font-size:14px}.icon-btn{height:40px;width:40px;border:1px solid rgba(249,231,184,.35);background:rgba(28,44,34,.5);border-radius:50%;color:#fff3ce;font-size:23px;cursor:pointer}.panel{background:var(--glass);border:1px solid var(--line);box-shadow:0 12px 40px rgba(17,29,21,.2);backdrop-filter:blur(16px);border-radius:13px}.quest-card{position:absolute;z-index:2;left:28px;top:88px;width:292px;padding:17px 18px 15px}.eyebrow{font-size:9px;font-weight:700;letter-spacing:1.9px;color:#e8ce8e}.sparkle{font-size:14px;margin-right:5px}.quest-title{font:600 19px/1.2 Fraunces,serif;margin:9px 0 5px;color:#fff4d8}.quest-copy{font-size:11px;line-height:1.55;color:#d0d1bd}.quest-progress{display:flex;align-items:center;gap:10px;margin-top:14px;font-size:10px;font-weight:700;color:#f1db9f}.progress-track{height:5px;flex:1;background:rgba(239,235,213,.2);border-radius:10px;overflow:hidden}.progress-track>div{height:100%;width:0;background:#e8c879;border-radius:10px;transition:width .4s}.quest-reward{font-size:10px;color:#d5cba9;margin-top:11px}.quest-reward:first-letter{color:#e8c879}.reputation{position:absolute;z-index:2;right:28px;top:88px;width:240px;padding:14px 15px 12px}.reputation-head{display:flex;justify-content:space-between;align-items:center;font-size:9px;letter-spacing:1.7px;font-weight:700;color:#ead69e}.reputation-head button{color:#f5e6bf;border:0;background:transparent;font-size:16px;cursor:pointer}.rep-list{margin-top:11px;display:grid;gap:9px}.rep-row{display:flex;align-items:center;gap:7px}.rep-icon{font-size:12px;width:16px;text-align:center}.cottage{color:#e6bf7d}.academy{color:#c6a9ec}.wilds{color:#a7ce8c}.rep-name{width:69px;font-size:10px;color:#e1e2cf}.rep-track{height:4px;flex:1;background:rgba(241,237,216,.18);border-radius:4px;overflow:hidden}.rep-track i{display:block;height:100%;width:18%;background:#dfbf79;border-radius:4px;transition:width .5s}.rep-row:nth-child(2) .rep-track i{background:#b8a0dd}.rep-row:nth-child(3) .rep-track i{background:#9acb85}.rep-row b{font-size:9px;min-width:16px;text-align:right;color:#f6ebce}.rep-note{border-top:1px solid rgba(240,225,183,.14);margin-top:11px;padding-top:9px;color:#b9c3aa;font:italic 11px Fraunces,serif}.reputation.collapsed .rep-list,.reputation.collapsed .rep-note{display:none}.reputation.collapsed{width:auto}.location{position:absolute;z-index:2;bottom:26px;left:28px;display:flex;align-items:center;gap:8px;font-size:9px;letter-spacing:2px;color:#f5f0d9;text-shadow:0 2px 6px #213628;font-weight:700}.location-dot{width:7px;height:7px;border-radius:50%;background:#eed37f;box-shadow:0 0 10px #ffe58f}.hint{position:absolute;z-index:2;bottom:70px;left:50%;transform:translateX(-50%);display:flex;gap:9px;align-items:center;padding:9px 14px;border:1px solid rgba(244,227,178,.3);background:rgba(22,39,29,.84);border-radius:30px;color:#fff4d7;font-size:11px;opacity:0;transition:opacity .2s;white-space:nowrap;pointer-events:none}.hint.visible{opacity:1}.keycap{background:#f1db9e;color:#25382b;border-radius:4px;padding:3px 6px;font-size:9px;font-weight:700}.toast{position:absolute;z-index:8;top:78px;left:50%;transform:translate(-50%,-10px);opacity:0;transition:.3s;background:#f3e7c8;color:#354432;border-radius:30px;padding:10px 18px;font-size:12px;font-weight:700;box-shadow:0 6px 24px #17251d55;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.dialogue-wrap{position:absolute;z-index:7;inset:0;display:none;align-items:flex-end;justify-content:center;padding:24px 24px max(24px,env(safe-area-inset-bottom));background:linear-gradient(0deg,rgba(14,26,20,.58),transparent 55%)}.dialogue-wrap.open{display:flex}.dialogue-card{width:min(600px,100%);padding:19px 22px 20px;background:rgba(27,42,33,.96)}.dialogue-person{display:flex;align-items:center;gap:12px}.portrait{width:42px;height:42px;display:grid;place-items:center;border:1px solid rgba(235,211,149,.4);border-radius:50%;background:#344a38;font-size:25px}.dialogue-name{font:600 19px Fraunces,serif;color:#fff1ce}.dialogue-role{font-size:8px;letter-spacing:1.5px;color:#c5c6ad;margin-top:3px}.dialogue-person button{margin-left:auto;background:none;border:0;color:#e5e3d0;font-size:25px;cursor:pointer}.dialogue-text{margin:17px 2px 14px;font:16px/1.45 Fraunces,serif;color:#f2ecd7}.choices{display:flex;gap:9px;flex-wrap:wrap}.choice{background:rgba(236,215,161,.08);border:1px solid rgba(236,215,161,.31);border-radius:8px;padding:10px 13px;color:#f2e8cc;text-align:left;font:500 11px 'DM Sans',sans-serif;cursor:pointer;transition:.2s;flex:1;min-width:145px}.choice:hover,.choice:focus{background:rgba(236,215,161,.2);border-color:#e4c879;outline:none}.choice em{font-style:normal;color:#e6cf93;display:block;font-size:9px;margin-top:5px}.mobile-controls{display:none;position:absolute;z-index:4;bottom:max(28px,env(safe-area-inset-bottom));left:22px;right:22px;align-items:flex-end;justify-content:space-between;pointer-events:none}.joystick,.action-button{pointer-events:auto;touch-action:none}.joystick{height:108px;width:108px;border-radius:50%;border:1px solid rgba(246,236,205,.27);background:rgba(24,41,31,.33);backdrop-filter:blur(5px);position:relative}.joy-knob{position:absolute;left:50%;top:50%;width:45px;height:45px;transform:translate(-50%,-50%);border:1px solid rgba(255,244,211,.5);border-radius:50%;background:rgba(234,216,165,.32);box-shadow:0 3px 12px #17241d55}.action-button{width:67px;height:67px;border:1px solid rgba(247,228,175,.55);border-radius:50%;background:rgba(34,53,39,.8);color:#f1d98d;font-size:23px;display:flex;flex-direction:column;justify-content:center;align-items:center;box-shadow:0 5px 16px #16251d66}.action-button small{font:700 8px 'DM Sans';letter-spacing:1.5px;color:#f3eedc;margin-top:1px}.help-pill{position:absolute;z-index:2;bottom:27px;left:50%;transform:translateX(-50%);color:rgba(247,240,220,.72);font-size:9px;letter-spacing:1px;white-space:nowrap;text-shadow:0 1px 5px #1c3023}.help-pill i{font-style:normal;margin:0 7px;color:#ebd58e}.mobile-help{display:none}.map-panel{position:absolute;z-index:6;left:50%;top:50%;transform:translate(-50%,-50%);width:min(440px,calc(100% - 32px));padding:18px;display:none;background:rgba(28,44,35,.96)}.map-panel.open{display:block}.map-heading{font:600 16px Fraunces,serif;letter-spacing:1.2px;color:#f3e6c1;display:flex;justify-content:space-between;align-items:center}.map-heading button{border:0;background:none;color:#eee5ca;font-size:23px}.map-art{height:230px;margin:14px 0 10px;position:relative;border-radius:9px;overflow:hidden;background:radial-gradient(ellipse at 30% 65%,#8caa76 0 13%,transparent 14%),radial-gradient(ellipse at 67% 25%,#94ad79 0 18%,transparent 19%),radial-gradient(ellipse at 55% 78%,#8ba875 0 19%,transparent 20%),linear-gradient(135deg,#607f5e,#76966b 45%,#8ba978);border:1px solid rgba(240,223,174,.22)}.map-art:before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(15deg,transparent 0 17px,rgba(226,224,177,.08) 18px 19px,transparent 20px 34px)}.map-path{position:absolute;width:60%;height:110%;left:23%;top:-4%;border:2px dashed rgba(242,222,168,.62);border-radius:48%;transform:rotate(32deg)}.map-you,.map-pin{position:absolute;color:#fff0bd;z-index:1;text-shadow:0 1px 5px #24372b}.map-you{left:34%;top:58%;font-size:22px}.pin-pip{left:24%;top:29%;color:#f0d996}.pin-academy{right:25%;top:21%;color:#e3c9f2}.pin-rowan{right:22%;bottom:22%;color:#f0d996}.map-label{position:absolute;z-index:1;color:#f4edd2;font-size:8px;letter-spacing:1px;text-shadow:0 1px 4px #203321}.label-you{left:40%;top:63%}.label-pip{left:8%;top:23%}.label-academy{right:5%;top:12%}.map-legend{display:flex;justify-content:space-between;font-size:9px;color:#ced5bd}.loading{position:absolute;z-index:10;inset:0;background:#829b72;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;color:#f8efd2;font:14px Fraunces,serif;letter-spacing:1px;transition:opacity .7s}.loading.done{opacity:0;pointer-events:none}.loading-flower{font-size:36px;color:#ead284;animation:turn 3s linear infinite}@keyframes turn{to{transform:rotate(360deg)}}
@media(max-width:700px){.topbar{left:16px;right:16px;top:max(13px,env(safe-area-inset-top))}.brand-mark{width:34px;height:34px;font-size:20px}.brand-name{font-size:14px}.brand-sub{font-size:7px;letter-spacing:2px}.day-pill{font-size:8px;padding:8px 10px;left:auto;right:51px;transform:none}.map-btn{width:34px;height:34px;font-size:20px}.quest-card{left:14px;top:62px;width:min(254px,calc(100% - 28px));padding:12px 13px}.eyebrow{font-size:8px}.quest-title{font-size:16px;margin:6px 0 4px}.quest-copy{font-size:10px;line-height:1.35}.quest-progress{margin-top:9px}.quest-reward{margin-top:7px;font-size:9px}.reputation{top:62px;right:14px;width:190px;padding:11px 11px 9px}.reputation-head{font-size:8px}.rep-list{gap:7px;margin-top:8px}.rep-name{width:54px;font-size:9px}.rep-note{margin-top:8px;padding-top:7px;font-size:10px}.location{left:16px;bottom:157px;font-size:8px}.mobile-controls{display:flex}.help-pill{bottom:12px;font-size:8px}.desktop-help{display:none}.mobile-help{display:inline}.hint{bottom:139px;font-size:10px}.dialogue-wrap{padding:16px 12px max(14px,env(safe-area-inset-bottom));align-items:flex-end}.dialogue-card{padding:15px 15px 16px}.dialogue-text{font-size:15px;margin:13px 2px}.choice{padding:10px;min-width:130px;font-size:10px}.dialogue-role{font-size:7px}.map-panel{padding:15px}.map-art{height:205px}}
@media(max-width:390px){.day-pill{display:none}.reputation{width:174px}.rep-name{width:48px}.quest-card{width:220px}.quest-copy{max-width:205px}.location{bottom:149px}}
@media(min-width:701px) and (max-height:620px){.quest-card,.reputation{top:70px}.location{bottom:15px}.help-pill{bottom:15px}}

import * as THREE from 'three';

const canvas = document.querySelector('#world');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#a9c49a');
scene.fog = new THREE.FogExp2('#a9c49a', 0.0075);
const camera = new THREE.PerspectiveCamera(42, innerWidth / innerHeight, .1, 180);
const renderer = new THREE.WebGLRenderer({canvas, antialias:true, alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.8));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;

scene.add(new THREE.HemisphereLight('#e9f4d5','#647454',2.05));
const sun = new THREE.DirectionalLight('#ffe3a2',2.35); sun.position.set(-28,40,22); sun.castShadow=true; sun.shadow.mapSize.set(1024,1024); sun.shadow.camera.left=-46;sun.shadow.camera.right=46;sun.shadow.camera.top=46;sun.shadow.camera.bottom=-46;sun.shadow.bias=-.0003;scene.add(sun);
const mat=(color,roughness=.9)=>new THREE.MeshStandardMaterial({color,roughness});
const groundMat=mat('#789766');
const groundGeo=new THREE.PlaneGeometry(190,190,58,58);groundGeo.rotateX(-Math.PI/2);
const pos=groundGeo.attributes.position;
for(let i=0;i<pos.count;i++){const x=pos.getX(i),z=pos.getZ(i);let y=Math.sin(x*.15+z*.08)*.22+Math.cos(z*.2)*.14; y+=Math.max(0,Math.abs(x)-43)*.09;pos.setY(i,y)}groundGeo.computeVertexNormals();
const ground=new THREE.Mesh(groundGeo,groundMat);ground.receiveShadow=true;scene.add(ground);
const grassMats=['#91a970','#859d67','#a4b77a','#718e61','#b2b77e'].map(c=>mat(c));
const pathMat=mat('#baaa7a');
function path(points,width){const verts=[];for(let i=0;i<points.length-1;i++){const a=points[i],b=points[i+1],dx=b[0]-a[0],dz=b[1]-a[1],len=Math.hypot(dx,dz),nx=dz/len*width/2,nz=-dx/len*width/2;verts.push(a[0]+nx,.025,a[1]+nz,a[0]-nx,.025,a[1]-nz,b[0]+nx,.025,b[1]+nz,b[0]-nx,.025,b[1]-nz)}const indices=[];for(let i=0;i<points.length-1;i++){const n=i*4;indices.push(n,n+1,n+2,n+1,n+3,n+2)}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));g.setIndex(indices);g.computeVertexNormals();const m=new THREE.Mesh(g,pathMat);m.receiveShadow=true;scene.add(m)}
path([[-2,17],[-1,10],[0,2],[4,-5],[4,-13],[1,-19],[-5,-25]],3.8);
path([[-1,1],[-8,-2],[-14,-5],[-20,-9]],3.1);path([[2,-6],[8,-13],[13,-20],[15,-29]],3);
const rand=(a,b)=>a+Math.random()*(b-a);
function addMesh(geo,material,parent,x,y,z,sx=1,sy=1,sz=1){const o=new THREE.Mesh(geo,material);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
// Soft rolling flower patches
for(let i=0;i<58;i++){const x=rand(-36,36),z=rand(-37,31);if(Math.abs(x)<4&&z<4&&z>-20)continue;const patch=addMesh(new THREE.CircleGeometry(rand(1.1,2.7),18),grassMats[Math.floor(Math.random()*grassMats.length)],scene,x,.035,z,1,.65,1);patch.rotation.x=-Math.PI/2;patch.castShadow=false}
// Village and academy landmarks
function cottage(x,z,scale=1,roof='#7d5946',wall='#e2d1a2'){
 const g=new THREE.Group();scene.add(g);g.position.set(x,0,z);g.scale.setScalar(scale);
 addMesh(new THREE.BoxGeometry(5.2,3.8,4.6),mat(wall),g,0,1.9,0);
 const roofGeo=new THREE.ConeGeometry(4.3,2.8,4);const r=addMesh(roofGeo,mat(roof),g,0,5,0,1,1,1);r.rotation.y=Math.PI/4;
 addMesh(new THREE.BoxGeometry(1.1,2.3,.16),mat('#694c36'),g,-.5,1.15,2.35);
 for(const wx of [-1.65,1.55]){addMesh(new THREE.BoxGeometry(.78,.9,.13),mat('#739b9a'),g,wx,2.45,2.36);addMesh(new THREE.BoxGeometry(.12,1,.18),mat('#f2ddb0'),g,wx,2.45,2.45);addMesh(new THREE.BoxGeometry(.86,.12,.18),mat('#f2ddb0'),g,wx,2.45,2.45)}
 addMesh(new THREE.CylinderGeometry(.14,.14,.35,8),mat('#a8895a'),g,.8,4.1,-.8);return g;
}
cottage(-18,-10,1.05,'#785349','#e5d8b2');cottage(-23,-14,.72,'#665b53','#d5d4ac');cottage(17,-9,.82,'#735447','#d4c597');
// Academy: welcoming tower and wings
const hall=new THREE.Group();scene.add(hall);hall.position.set(13,0,-31);
addMesh(new THREE.BoxGeometry(13,8,7),mat('#b9ae91'),hall,0,4,0);
addMesh(new THREE.BoxGeometry(6.7,11,6.7),mat('#c5b99b'),hall,-1.7,5.5,-4.5);
const towerRoof=addMesh(new THREE.ConeGeometry(4.8,4.8,5),mat('#554d66'),hall,-1.7,13.4,-4.5);towerRoof.rotation.y=.35;
addMesh(new THREE.ConeGeometry(3.8,3.5,5),mat('#65556f'),hall,0,9.5,0);
addMesh(new THREE.BoxGeometry(1.5,3.4,.15),mat('#564d43'),hall,0,1.7,3.57);
for(let y of [3.7,6.2,8.7]){addMesh(new THREE.BoxGeometry(.65,1.1,.12),mat('#94b7b2'),hall,-1.7,y,-1.03);}
// Stone lanterns at the path
const stone=mat('#aea88a'), lanternGlow=new THREE.MeshStandardMaterial({color:'#ffe79a',emissive:'#ffce68',emissiveIntensity:1.6});
for(const [x,z] of [[-2,7],[1,-10],[3,-19],[-10,-4],[9,-16]]){const l=new THREE.Group();scene.add(l);l.position.set(x,0,z);addMesh(new THREE.CylinderGeometry(.34,.48,1.4,6),stone,l,0,.7,0);addMesh(new THREE.BoxGeometry(.92,.17,.92),stone,l,0,1.4,0);addMesh(new THREE.BoxGeometry(.52,.56,.52),lanternGlow,l,0,1.78,0);addMesh(new THREE.ConeGeometry(.68,.35,4),stone,l,0,2.24,0)}
// Enchanted, varied trees
const trunkMat=mat('#70553c');const leafMats=['#627e59','#739061','#829a65','#526f59'].map(c=>mat(c));
function tree(x,z,size=1,kind=0){const t=new THREE.Group();scene.add(t);t.position.set(x,0,z);t.scale.setScalar(size);addMesh(new THREE.CylinderGeometry(.22,.38,3.4,7),trunkMat,t,0,1.7,0);const lm=leafMats[Math.floor(Math.random()*leafMats.length)];if(kind===0){for(let i=0;i<3;i++)addMesh(new THREE.IcosahedronGeometry(1.8-i*.15,1),lm,t,rand(-.4,.4),3.3+i*1.1,rand(-.3,.3),1.1,1,.95)}else{for(let i=0;i<3;i++){const b=addMesh(new THREE.ConeGeometry(1.5-i*.22,2.6,7),lm,t,0,3.2+i*1.5,0);b.rotation.y=.3}}}
for(const [x,z,s,k] of [[-29,-3,1.25,0],[-31,-14,1.4,0],[-27,5,.9,1],[-13,-22,.95,0],[-7,-31,1.25,0],[4,-34,.9,1],[25,-22,1.4,0],[27,-5,1,1],[25,8,1.35,0],[8,11,.85,0],[-14,12,1.2,1],[-34,-26,1.5,1],[33,-31,1.4,0],[31,12,1.6,1],[-36,16,1.25,0]])tree(x,z,s,k);
// tiny flowers dot the meadows
const flowerColors=['#f5d992','#eab8b7','#d8c6ec','#f2e9cf'];
for(let i=0;i<170;i++){const x=rand(-35,35),z=rand(-33,24);if(Math.abs(x)<5&&z<7&&z>-20)continue;const flower=addMesh(new THREE.SphereGeometry(.09,6,5),mat(flowerColors[i%flowerColors.length]),scene,x,rand(.16,.3),z,1,1.6,1);flower.castShadow=false}
// Player model
const player=new THREE.Group();scene.add(player);player.position.set(0,0,8);
const playerBody=new THREE.Group();player.add(playerBody);
const robe=mat('#554f7c'), robeLight=mat('#766e9d'), skin=mat('#e6bb91'), gold=mat('#ddc071'), dark=mat('#383445');
addMesh(new THREE.ConeGeometry(.72,1.9,8),robe,playerBody,0,1.05,0);addMesh(new THREE.SphereGeometry(.4,12,10),skin,playerBody,0,2.2,0);
addMesh(new THREE.ConeGeometry(.72,.95,8),robeLight,playerBody,0,2.95,0);addMesh(new THREE.ConeGeometry(.68,.35,8),gold,playerBody,0,2.48,0);addMesh(new THREE.ConeGeometry(.31,1,8),robe,playerBody,0,3.55,0);
addMesh(new THREE.BoxGeometry(.15,.55,.09),gold,playerBody,.32,1.4,.25); // wand glint
// A hovering, friendly moth follows the player
const moth=new THREE.Group();player.add(moth);moth.position.set(.9,2.5,.4);const mothMat=new THREE.MeshStandardMaterial({color:'#fff1ad',emissive:'#f8d575',emissiveIntensity:1.1});addMesh(new THREE.SphereGeometry(.14,8,8),mothMat,moth,0,0,0);addMesh(new THREE.SphereGeometry(.17,8,6),mat('#faf0cb'),moth,-.16,.06,0,.65,1,.25);addMesh(new THREE.SphereGeometry(.17,8,6),mat('#faf0cb'),moth,.16,.06,0,.65,1,.25);

const stars=[];const starGeo=new THREE.OctahedronGeometry(.28,0),starMat=new THREE.MeshStandardMaterial({color:'#fff1a4',emissive:'#ffdc68',emissiveIntensity:2});
for(const [x,z] of [[-5,1],[3,-1],[-8,-10],[6,-17],[-2,-21],[10,-5],[19,-22]]){const s=new THREE.Mesh(starGeo,starMat);s.position.set(x,.85,z);s.castShadow=true;scene.add(s);stars.push({mesh:s,base:s.position.y,taken:false})}

const npcDefs=[
 {id:'pip',name:'Pip',role:'BRIDGE KEEPER',emoji:'🐇',x:4,z:-13,color:'#d4b28b',coat:'#a97457',kind:'rabbit',bond:0,place:'THE OLD FOOTBRIDGE'},
 {id:'rowan',name:'Rowan',role:'WILLOWMEAD GARDENER',emoji:'🦊',x:-14,z:-5,color:'#cb8b5b',coat:'#f2ead2',kind:'fox',bond:0,place:'WILLOWMEAD COTTAGES'},
